from lib import *
S = SS('x4')
steps = [
    step("BeanPostProcessor 可以把 Bean 换成别的对象。Wrap 把 SvcImpl 换成了一个只实现 Svc 接口的 JDK 动态代理。按接口 Svc 注入的 ByIface 拿到 $Proxy10,调用返回 [包装]hi。getBean(\"svc\") 的类型是 $Proxy10,不是 SvcImpl 的实例。按具体类 SvcImpl 注入的 ByClass 失败:UnsatisfiedDependencyException,原因是 BeanNotOfRequiredTypeException:Bean named 'svc' is expected to be of type 'demo.Main$SvcImpl' but was actually of type 'jdk.proxy2.$Proxy10'。", t=tl(S(1)), mark=lidx(S(1), '异常 UnsatisfiedDependencyException'), done=lidx(S(1), 'ByIface 拿到', 'getBean("svc") 的类型'), b=bars([['按接口注入拿到代理', 1, '成功($Proxy10)'], ['getBean 是 SvcImpl 的实例', 0, 'false'], ['按具体类注入', 0, '失败(BeanNotOfRequiredTypeException)']], 1, done=[0], cur=[1], mark=[2]), kv=KV([['按接口 Svc 注入', '拿到 $Proxy10,可用'], ['getBean(svc) 的类型', '$Proxy10'], ['按具体类 SvcImpl 注入', 'BeanNotOfRequiredTypeException'], ['含义', 'BPP 能换掉对象的类型']], ['按具体类 SvcImpl 注入'])),
    step("多个 BeanPostProcessor 的执行顺序(同一个 Bean,postProcessBeforeInitialization)。PriorityOrdered(5)、PriorityOrdered(10)、Ordered(0)、Ordered(1)、plain1(没有顺序、最先注册)、plain2(没有顺序、后注册)。PriorityOrdered 全部在 Ordered 之前,各组内部按 getOrder 从小到大,没有顺序的最后,按注册顺序。", t=tl(S(2)), mark=lidx(S(2), '顺序:PriorityOrdered(5)'), b=bars([['PriorityOrdered(5)', 1, '第 1'], ['PriorityOrdered(10)', 2, '第 2'], ['Ordered(0)', 3, '第 3'], ['Ordered(1)', 4, '第 4'], ['plain1', 5, '第 5'], ['plain2', 6, '第 6']], 6, done=[0, 1], cur=[2, 3], mark=[4, 5]), kv=KV([['第一组', 'PriorityOrdered,按 order 升序'], ['第二组', 'Ordered,按 order 升序'], ['第三组', '没有顺序,按注册顺序'], ['先后', '组与组之间固定']], ['第一组'])),
    step("创建得太早的 Bean 不会被所有 BeanPostProcessor 处理。Early 是 BPP,构造器依赖 Service,而 Service 的 @Bean 方法不是 static,所以 EarlyConf 和 Service 都在注册 BPP 的阶段被提前创建。Spring 打出 WARN:Bean 'main.EarlyConf' 与 Bean 'service' ... is not eligible for getting processed by all BeanPostProcessors (for example: not eligible for auto-proxying)。后注册的 Late(BPP)只看到了 plainBean,没有看到 service。", t=tl(S(3)), mark=lidx(S(3), "Bean 'service' of type", "Late(后注册的 BPP)看到了"), done=lidx(S(3), "Bean 'main.EarlyConf'", '构造 Service'), b=bars([['WARN 提示的被提前创建的 Bean 数', 2, '2(EarlyConf、service)'], ['Late 看到的 plainBean', 1, '看到'], ['Late 看到的 service', 0, '没看到']], 2, cur=[0], done=[1], mark=[2]), kv=KV([['Early', 'BPP,构造器依赖 Service'], ['被提前创建', 'EarlyConf 和 service'], ['日志级别', 'WARN'], ['后果', 'Late 没处理 service(代理等对它不生效)']], ['后果'])),
    step("BeanFactoryPostProcessor 的 @Bean 方法要不要 static。(a)非 static:Spring 打出 INFO:@Bean method NonStatic.bfpp is non-static and returns an object assignable to Spring's BeanFactoryPostProcessor interface ... Add the 'static' modifier。方法被调用时,配置类里 @Autowired 的 Environment 字段是 null。(b)static:方法被调用时不需要先创建配置类;配置类后来被创建时 @Autowired 字段正常注入。BFPP 和 BPP 的 @Bean 方法都应该写成 static。", t=tl(S(4)), mark=lidx(S(4), '非 static 的 BFPP @Bean 方法被调用时', 'NonStatic.bfpp is non-static'), done=lidx(S(4), 'static 的 BFPP @Bean 方法被调用', '配置类被创建后'), b=bars([['非 static:@Autowired 字段被注入', 0, 'null'], ['static:配置类里的 @Autowired 字段', 1, '已注入']], 1, mark=[0], done=[1]), kv=KV([['非 static', 'INFO 提示 + @Autowired 字段为 null'], ['static', '不用先创建配置类'], ['原因', '创建配置类时 BPP 还没注册'], ['规则', 'BFPP 与 BPP 的 @Bean 写成 static']], ['非 static'])),
]
A = mkartx('x4', 4, 'Spring,BeanPostProcessor,BeanFactoryPostProcessor,扩展点,真实验证,动画演示',
    '实测容器的两个扩展点:BeanPostProcessor 能把 Bean 换成 JDK 代理(按具体类注入就失败);多个 BPP 按 PriorityOrdered、Ordered、无顺序三组执行;被提前创建的 Bean(Early 构造器依赖 Service)不会被后注册的 BPP 处理,Spring 会打 WARN;BFPP 的 @Bean 方法非 static 时,配置类里的 @Autowired 字段是 null。',
    'BeanPostProcessor 和 BeanFactoryPostProcessor 能做什么、会在哪里出问题?返回代理对象之后按具体类注入为什么失败?多个 BPP 谁先谁后?为什么 BPP 依赖的 Bean 会“不被所有 BPP 处理”?为什么 BFPP 的 @Bean 方法必须 static?这篇在 Spring Framework 7.0.9 上逐项验证。',
    [('第 5 / 6', '没有顺序的两个 BPP 在 6 个 BPP 里的位置(PriorityOrdered 和 Ordered 之后)'), ('2 个', 'Early 的构造器依赖被提前创建、后注册的 BPP 没有处理的 Bean 数(EarlyConf 与 service)'), ('null', '非 static 的 BFPP @Bean 方法被调用时,配置类里 @Autowired 字段的值')],
    [('换掉对象', '<p>BPP 返回的对象会替换原 Bean;返回 JDK 代理后,按具体类注入会失败。</p>'),
     ('执行顺序', '<p>PriorityOrdered、Ordered、无顺序三组,组内按 getOrder 升序,无顺序的按注册顺序。</p>'),
     ('过早创建', '<p>BPP 依赖的 Bean 在 BPP 注册阶段就被创建,后注册的 BPP 处理不到,Spring 打 WARN 提示。</p>'),
     ('BFPP 要 static', '<p>非 static 的 BFPP @Bean 方法需要先创建配置类,这时注解处理还没有就绪。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9;日志通过 logback.xml(INFO)输出,只摘录了 Spring 提示的几行,过长的行在末尾截断',
     '没有验证:用 CGLIB 代理(proxyTargetClass)替换 Bean 时按具体类注入是否成功(Spring AOP 的代理见后面的 AOP 篇);BeanDefinitionRegistryPostProcessor 的顺序;InstantiationAwareBeanPostProcessor 在 postProcessBeforeInstantiation 里直接返回对象的情形;Boot 里自带的 BPP 数量'],
    'BeanPostProcessor 与 BeanFactoryPostProcessor')
